// Hand-written. Not generated by Speakeasy.
//
// Guards the hand edits in provider.go against being lost.
//
// provider.go is generated, and our edits survive regeneration only through
// Speakeasy's persistentEdits three-way merge. That merge is reliable but not
// guaranteed: a conflict fails loudly, but a mis-set baseline can drop an edit
// quietly, which happened once during development after a routine `git checkout`
// of a generated file was absorbed as an intentional change.
//
// Losing the idp_host attribute would not break the build. It would leave
// Dedicated Cloud and On-Premise customers unable to create or delete a service,
// discovered only in production. These tests turn that silent failure into a
// failing build.
package provider

import (
	"context"
	"net/http"
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/provider"
)

func providerSchema(t *testing.T) map[string]any {
	t.Helper()
	p := New("test")()
	resp := &provider.SchemaResponse{}
	p.Schema(context.Background(), provider.SchemaRequest{}, resp)
	if resp.Diagnostics.HasError() {
		t.Fatalf("provider schema has errors: %v", resp.Diagnostics)
	}
	out := map[string]any{}
	for name, attr := range resp.Schema.Attributes {
		out[name] = attr
	}
	return out
}

func TestProviderExposesHandAddedAttributes(t *testing.T) {
	attrs := providerSchema(t)
	for name, why := range map[string]string{
		"idp_host": "Dedicated Cloud and On-Premise customers cannot reach their own IdP, " +
			"so service create and delete both fail",
		"organization_id": "services cannot be created at all, and configurations using " +
			"provider aliases would silently fall back to one organization",
	} {
		if _, ok := attrs[name]; !ok {
			t.Errorf("provider schema has no `%s` attribute: %s.\n"+
				"This is a hand edit in provider.go carried by persistentEdits and has most "+
				"likely been dropped by a regeneration. Re-apply the hunks marked "+
				"`idp_host, organization_id: hand-added`.", name, why)
		}
	}
}

// TestOrganizationIDFallsBackToEnv guards the env fallback, which run.sh and CI
// depend on.
func TestOrganizationIDFallsBackToEnv(t *testing.T) {
	t.Setenv("AUTHLETE_ORGANIZATION_ID", "417639873643986")
	if got := OrganizationIDFromEnv(); got != 417639873643986 {
		t.Fatalf("OrganizationIDFromEnv() = %d, want 417639873643986", got)
	}
	t.Setenv("AUTHLETE_ORGANIZATION_ID", "not-a-number")
	if got := OrganizationIDFromEnv(); got != 0 {
		t.Fatalf("a malformed value should yield 0, got %d", got)
	}
}

// The attributes below are configuration, not hand edits -- they come from
// gen.yaml. They are asserted here because losing them is equally silent: the
// provider still builds and the shared-cloud path still works.
func TestProviderExposesConfiguredAttributes(t *testing.T) {
	attrs := providerSchema(t)
	for name, why := range map[string]string{
		"bearer":          "credentials would have to be hardcoded (environmentVariables in gen.yaml)",
		"server_url":      "customers could not select their regional cluster",
		"tls_skip_verify": "on-premise behind a private CA would fail (additionalProviderAttributes)",
		"http_headers":    "proxy and custom-header setups would fail (additionalProviderAttributes)",
	} {
		if _, ok := attrs[name]; !ok {
			t.Errorf("provider schema has no `%s` attribute: %s", name, why)
		}
	}
}

// TestTransportIsWrapped guards the third hunk: the line in Configure that wraps
// the generated transport. The attribute can exist while the wrapper is gone, in
// which case idp_host would be accepted and silently ignored -- the worst of both
// outcomes, since the customer sees no error.
func TestTransportIsWrapped(t *testing.T) {
	inner := &capture{}
	rt := NewIdpRoutingTransport("idp.internal", 0, 0, inner)

	if rt == http.RoundTripper(inner) {
		t.Fatal("NewIdpRoutingTransport returned the inner transport unchanged for a " +
			"configured idp_host; IdP requests would not be rerouted")
	}
	send(t, rt, defaultIdpOrigin()+"/api/service")
	if len(inner.got) != 1 || inner.got[0] != "https://idp.internal/api/service" {
		t.Fatalf("IdP request was not rerouted: %v", inner.got)
	}
}
